"""Mutalia-e-Quran XII PDF58: p.55 — verses 5:3–4 (5:5 begins at the foot; recorded on p.56). Run: python class12_quran_page058.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p58():
    b = Builder()
    V(b, 5, 3, 'تم پر حرام کر دیا گیا ہے مُردار اور خون اور خنزیر کا گوشت اور جس پر (ذبح کے وقت) اللہ کے سوا کسی اور کا نام پکارا جائے اور گلا گھٹنے سے مرنے والا اور چوٹ لگنے سے مرنے والا اور اوپر سے گر کر مرنے والا اور سینگ لگنے سے مرنے والا اور جسے کھا لیا ہو کسی درندے نے سوائے اُس کے جسے تم (اس کے مرنے سے پہلے) ذبح کر لو اور جسے بتوں کی قربان گاہ پر ذبح کیا گیا ہو اور یہ کہ تم جوئے کے تیروں سے (گوشت وغیرہ) تقسیم کرو (یہ بھی حرام ہے) یہ سخت گناہ کے کام ہیں آج وہ لوگ جنھوں نے کفر کیا ہے تمھارے دین (کے مغلوب ہونے) سے ناامید ہو گئے تو (مسلمانو!) اُن سے مت ڈرو اور مجھ سے ڈرو آج کے دن میں نے تمھارے لیے تمھارا دین مکمل کر دیا اور تم پر اپنی نعمت پوری کر دی اور تمھارے لیے اسلام بطورِ دین پسند کر لیا پھر جو شدتِ بھوک سے مجبور ہو جائے گناہ کی طرف مائل ہونے والا نہ ہو (اور مجبوراً حرام میں سے جان بچانے کے بقدر کچھ کھا لے) تو بے شک اللہ بڑا ہی بخشنے والا نہایت رحم فرمانے والا ہے۔',
      'پر تاسو حرام کړای شول: مردار، وینه، د خنزیر غوښه، او هغه چې پر هغه (د ذبح پر مهال) له الله پرته د بل چا نوم یاد شي، او په غاړه زندۍ مړ شوی، او په ګوزار مړ شوی، او له پاسه لوېدلی مړ شوی، او په ښکر وهل شوی مړ شوی، او هغه چې کوم ځناور خوړلی وي — پرته له هغه چې تاسو یې (له مړینې مخکې) ذبح کړئ — او هغه چې د بتانو پر قربانځای ذبح شوی وي، او دا چې د قمار په غشو (غوښه او نور) ووېشئ (دا هم حرام دي)؛ دا د سختې ګناه کارونه دي. نن هغه کسان چې کفر یې کړی، ستاسو له دین (د مغلوبېدو) نهیلي شول؛ نو (ای مسلمانانو!) له هغوی مه وېرېږئ او له ما ووېرېږئ. نن ما تاسو ته ستاسو دین بشپړ کړ، پر تاسو مې خپل نعمت پوره کړ، او تاسو ته مې اسلام د دین په توګه غوره کړ. بیا څوک چې د لوږې له سختۍ اړ شي، په داسې حال کې چې ګناه ته مایل نه وي (او په اړتیا د ځان ژغورلو په اندازه له حرامو څه وخوري)، نو بې‌شکه الله ډېر بښونکی، بې‌حده مهربان دی.')
    V(b, 5, 4, 'وہ آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) سے سوال کرتے ہیں اُن کے لیے کیا حلال کیا گیا ہے؟ آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) فرما دیجیے کہ تمھارے لیے پاکیزہ چیزیں حلال کی گئی ہیں اور وہ شکاری جانور جنھیں تم نے شکار پر دوڑاتے ہوئے سدھا لیا ہے تم انھیں (شکار کے وہ طریقے) سکھاتے ہو جو تمھیں اللہ نے سکھائے ہیں تو اُس میں سے (بھی) کھاؤ جو وہ تمھارے لیے پکڑ رکھیں اور (شکاری جانور کو چھوڑتے وقت) اس پر اللہ کا نام لو اور اللہ (کی نافرمانی) سے ڈرو بے شک اللہ بہت جلد حساب لینے والا ہے۔',
      'هغوی له تاسو (صلی الله علیه وعلی آله واصحابه وسلم) پوښتنه کوي چې دوی ته څه حلال شوي؟ ووایئ: تاسو ته پاک شیان حلال شوي، او هغه ښکاري ځناور چې تاسو د ښکار پر لور په ځغلولو روزلي — تاسو ورته (د ښکار هغه طریقې) ور زده کوئ چې الله تاسو ته در زده کړې — نو له هغه (هم) وخورئ چې هغوی تاسو ته ونیسي، او (د ښکاري ځناور د خوشې کولو پر مهال) پرې د الله نوم واخلئ، او له الله (د نافرمانۍ) ووېرېږئ؛ بې‌شکه الله ډېر ژر حساب اخیستونکی دی.')
    BOOK.save(58, [(6, rec(b, 6, 58, 58))], issues=[{'id': 'mq12-pdf058', 'unit': 6, 'printedPage': 55,
               'description': 'Verse 5:5 begins on the last line of p.55 and is recorded with p.56.'}])


